fun findDuplicateCharacters(input: String): List<Char> {
    val seen = mutableSetOf<Char>()
    val duplicates = mutableListOf<Char>()
    for (char in input) {
        if (!seen.add(char) && char !in duplicates) duplicates.add(char)
