fun findDuplicateCharacters(input: String): List<Char> {
    val counts = mutableMapOf<Char, Int>()
    for (char in input) counts[char] = (counts[char] ?: 0) + 1
    return input.filter { counts[it]!! > 1 }.distinct()
}

fun findDuplicateCharacters(input: String): List<Char> {
    return input.asSequence().groupingBy { it }.eachCount().filterValues { it > 1 }.keys.toList()
}

